//! Real-world RFC 3161 timestamp token corpus (16 tokens, 4 TSAs)
//!
//! Extracted from real ATL receipts issued by four independent free TSAs
//! (FreeTSA, Sectigo, DigiCert, GlobalSign) during the algorithm survey that
//! motivated this module: `docs-md/atl-trust-model-decisions.md`.
//!
//! FreeTSA and GlobalSign embed a genuinely self-signed root in the token;
//! Sectigo and DigiCert embed a "root" that is itself cross-signed by an
//! absent legacy root, so without a TrustStore chain construction correctly
//! reports `Incomplete` (not `Invalid` -- the token is not broken, it is just
//! missing a certificate a caller would have to supply externally), and with
//! a TrustStore pinning the token's own top certificate it reports `Trusted`.
#![cfg(feature = "rfc3161-verify")]

use crate::core::verify::anchors::rfc3161::{verify_rfc3161_token, TrustStore};
use crate::core::verify::{PathStatus, TerminalAnchor};

struct CorpusEntry {
    receipt_id: &'static str,
    tsa: &'static str,
    token_b64: &'static str,
    target_hash_hex: &'static str,
    /// SHA-256 hash of the trust anchor's SubjectPublicKeyInfo, present in
    /// the token's own certificate set (self-signed for FreeTSA/GlobalSign,
    /// cross-signed-but-still-embedded for Sectigo/DigiCert).
    anchor_spki_pin_hex: &'static str,
    /// Whether the anchor is genuinely self-signed (FreeTSA, GlobalSign) or
    /// cross-signed by a certificate absent from the token (Sectigo, DigiCert).
    anchor_self_signed: bool,
}

