fn expected_root(entry: &CorpusEntry) -> [u8; 32] {
    let mut out = [0u8; 32];
    hex::decode_to_slice(entry.target_hash_hex, &mut out).expect("valid hex in corpus fixture");
    out
}

fn anchor_pin(entry: &CorpusEntry) -> [u8; 32] {
    let mut out = [0u8; 32];
    hex::decode_to_slice(entry.anchor_spki_pin_hex, &mut out).expect("valid hex in corpus fixture");
    out
}

/// Every token in the corpus verifies fully -- imprint, CMS signature, chain,
/// EKU -- when the caller supplies a TrustStore pinning the token's own
/// top-of-chain certificate. This is the acceptance criterion "all 16 real
/// tokens pass the math", covering all four observed TSAs and the full
/// algorithm matrix: ECDSA-SHA512/P-384 (FreeTSA), bare-OID RSA/SHA-384
/// 4096-bit (Sectigo), bare-OID RSA/SHA-256 4096-bit (DigiCert), and
/// composite-OID RSA/SHA-384 3072-bit with CMS Algorithm Protection
/// (GlobalSign).
#[test]
fn corpus_all_16_tokens_pass_with_trust_store() {
    for entry in CORPUS {
        let token_der = format!("base64:{}", entry.token_b64);
        let root = expected_root(entry);
        let store = TrustStore::new().with_anchor_spki_pin(anchor_pin(entry));

        let facts = verify_rfc3161_token(&token_der, &root, Some(&store))
            .unwrap_or_else(|e| panic!("{} ({}): parse failed: {e}", entry.receipt_id, entry.tsa));

        assert!(
            facts.message_imprint.is_verified(),
            "{} ({}): imprint mismatch",
            entry.receipt_id,
            entry.tsa
        );
        assert!(
            facts.cms_signature.is_verified(),
            "{} ({}): CMS signature invalid: {:?}",
            entry.receipt_id,
            entry.tsa,
            facts.diagnostic
        );
        assert!(
            facts.chain_valid_at_gen_time,
            "{} ({}): chain invalid at genTime",
            entry.receipt_id, entry.tsa
        );
        assert!(
            facts.timestamping_eku_ok,
            "{} ({}): EKU check failed",
            entry.receipt_id, entry.tsa
        );
        assert_eq!(
            facts.path_status,
            PathStatus::Complete,
            "{} ({}): expected Complete path",
            entry.receipt_id,
            entry.tsa
        );
        assert!(
            matches!(facts.terminal_anchor, Some(TerminalAnchor::Trusted { .. })),
            "{} ({}): expected Trusted terminal anchor, got {:?}",
            entry.receipt_id,
            entry.tsa,
            facts.terminal_anchor
        );
        assert!(
            facts.is_fully_valid(),
            "{} ({}): expected aggregate success with TrustStore configured",
            entry.receipt_id,
            entry.tsa
        );
    }
}

/// Without any TrustStore, no token in the corpus ever reaches `Trusted` or
/// contributes to aggregate success -- regardless of whether its embedded
/// "root" happens to be self-signed (FreeTSA, GlobalSign: terminates
/// `Assumed`) or cross-signed by an absent legacy root (Sectigo, DigiCert:
/// chain construction correctly reports `Incomplete`, not `Invalid` -- the
/// certificates present are all cryptographically sound, there just isn't
/// enough material to reach a terminus).
#[test]
fn corpus_all_16_tokens_never_trusted_without_store() {
    for entry in CORPUS {
        let token_der = format!("base64:{}", entry.token_b64);
        let root = expected_root(entry);

        let facts = verify_rfc3161_token(&token_der, &root, None)
            .unwrap_or_else(|e| panic!("{} ({}): parse failed: {e}", entry.receipt_id, entry.tsa));

        assert!(
            !facts.is_fully_valid(),
            "{} ({}): must not succeed without a TrustStore",
            entry.receipt_id,
            entry.tsa
        );
        assert!(
            !matches!(facts.terminal_anchor, Some(TerminalAnchor::Trusted { .. })),
            "{} ({}): must never be Trusted without a TrustStore",
            entry.receipt_id,
            entry.tsa
        );

        // The math itself (signature, chain crypto, EKU) is independent of
        // trust and must still hold.
        assert!(
            facts.message_imprint.is_verified(),
            "{} ({}): imprint mismatch",
            entry.receipt_id,
            entry.tsa
        );
        assert!(
            facts.cms_signature.is_verified(),
            "{} ({}): CMS signature invalid",
            entry.receipt_id,
            entry.tsa
        );
        assert!(
            facts.timestamping_eku_ok,
            "{} ({}): EKU check failed",
            entry.receipt_id, entry.tsa
        );

        if entry.anchor_self_signed {
            assert_eq!(
                facts.path_status,
                PathStatus::Complete,
                "{} ({}): self-signed root should yield a Complete (Assumed) path",
                entry.receipt_id,
                entry.tsa
            );
            assert!(
                matches!(facts.terminal_anchor, Some(TerminalAnchor::Assumed { .. })),
                "{} ({}): expected Assumed terminal anchor, got {:?}",
                entry.receipt_id,
                entry.tsa,
                facts.terminal_anchor
            );
        } else {
            assert_eq!(
                facts.path_status,
                PathStatus::Incomplete,
                "{} ({}): cross-signed root missing its issuer should yield Incomplete, not Invalid",
                entry.receipt_id,
                entry.tsa
            );
            assert!(facts.terminal_anchor.is_none());
        }
    }
}

/// Sanity check that the corpus actually covers all four TSAs (guards
/// against this fixture silently losing coverage in a future edit).
#[test]
fn corpus_covers_all_four_tsas() {
    use std::collections::BTreeSet;
    let tsas: BTreeSet<&str> = CORPUS.iter().map(|e| e.tsa).collect();
    assert_eq!(tsas, BTreeSet::from(["FREETSA", "SECTIGO", "DIGICERT", "GLOBALSIGN"]));
    assert_eq!(CORPUS.len(), 16);
}
